import {
  ChangeDetectionStrategy,
  Component,
  DestroyRef,
  ElementRef,
  afterNextRender,
  computed,
  inject,
  signal,
} from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { Subscription } from 'rxjs';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { StepperComponent } from '../../shared/ui/stepper/stepper.component';
import { WizardCountry } from '../quote-wizard/wizard-country.service';
import { FormFieldComponent, fieldInputId } from './components/form-field/form-field.component';
import { FormFieldDescriptor, FormSections } from './data/form-field.model';
import { FormFieldService } from './data/form-field.service';
import { buildValidators } from './validation/build-validators';
import { FieldValue } from './validation/validation.model';

type Step1Group = FormGroup<Record<string, FormControl<FieldValue>>>;

interface SectionView {
  id: 'policyholder' | 'vehicle';
  title: string;
  fields: { field: FormFieldDescriptor; delay: number }[];
  titleDelay: number;
}

const SECTION_TITLES: Record<SectionView['id'], string> = {
  policyholder: 'Tus datos',
  vehicle: 'Tu vehículo',
};

/**
 * Value restored from the session for a field: the wrong type falls back to empty, and a select
 * value that is no longer one of its options (renamed or removed in the CMS) is dropped (R-13).
 */
export function restoredValue(field: FormFieldDescriptor, saved: FieldValue | undefined): FieldValue {
  if (field.type === 'checkbox') return typeof saved === 'boolean' ? saved : false;
  if (typeof saved !== 'string') return '';
  if (field.type === 'select' && !field.options.some((o) => o.value === saved)) return '';
  return saved;
}

@Component({
  selector: 'app-step1-form-page',
  imports: [ReactiveFormsModule, StepperComponent, FormFieldComponent],
  changeDetection: ChangeDetectionStrategy.OnPush,
  templateUrl: './step1-form.page.html',
  styleUrl: './step1-form.page.scss',
})
export class Step1FormPage {
  private readonly wizardCountry = inject(WizardCountry);
  private readonly fieldService = inject(FormFieldService);
  private readonly session = inject(QuoteSessionStore);
  private readonly router = inject(Router);
  private readonly route = inject(ActivatedRoute);
  private readonly host = inject<ElementRef<HTMLElement>>(ElementRef);
  private readonly destroyRef = inject(DestroyRef);

  protected readonly steps = ['Tus datos', 'Elige tu plan', 'Resumen'];
  protected readonly loading = signal(true);
  protected readonly failed = signal(false);
  protected readonly submitted = signal(false);
  protected readonly statusMessage = signal('');
  protected readonly form = signal<Step1Group | null>(null);
  private readonly loaded = signal<FormSections | null>(null);
  private loadSub: Subscription | null = null;

  protected readonly sections = computed<SectionView[]>(() => {
    const data = this.loaded();
    if (!data) return [];
    let index = 1; // 0 is the card header
    const views: SectionView[] = [];
    for (const id of ['policyholder', 'vehicle'] as const) {
      const fields = data[id];
      if (fields.length === 0) continue;
      const titleDelay = index++;
      views.push({
        id,
        title: SECTION_TITLES[id],
        titleDelay,
        fields: fields.map((field) => ({ field, delay: index++ })),
      });
    }
    return views;
  });
  protected readonly isEmpty = computed(
    () => !this.loading() && !this.failed() && this.sections().length === 0,
  );
  protected readonly buttonDelay = computed(
    () => 1 + this.sections().reduce((n, s) => n + 1 + s.fields.length, 0),
  );

  constructor() {
    afterNextRender(() => this.host.nativeElement.querySelector<HTMLElement>('h1')?.focus());
    this.load();
  }

  protected load(): void {
    const country = this.wizardCountry.country();
    if (!country) return;
    this.loadSub?.unsubscribe();
    this.loading.set(true);
    this.failed.set(false);
    this.loadSub = this.fieldService.load(country.code).subscribe({
      next: (sections) => {
        this.form.set(this.buildForm(sections, country.legalAge));
        this.loaded.set(sections);
        this.loading.set(false);
      },
      error: () => {
        this.failed.set(true);
        this.loading.set(false);
      },
    });
  }

  private buildForm(sections: FormSections, legalAge: number): Step1Group {
    const stored = this.session.readStep1();
    const today = new Date();
    const controls: Record<string, FormControl<FieldValue>> = {};
    for (const field of [...sections.policyholder, ...sections.vehicle]) {
      const initial = restoredValue(field, stored[field.key]);
      controls[field.key] = new FormControl<FieldValue>(initial, {
        nonNullable: true,
        validators: buildValidators(field.rules, { legalAge, today }, field.key),
      });
    }
    const group: Step1Group = new FormGroup(controls);
    group.valueChanges
      .pipe(takeUntilDestroyed(this.destroyRef))
      .subscribe(() => this.session.saveStep1(group.getRawValue()));
    return group;
  }

  protected control(key: string): FormControl<FieldValue> {
    return this.form()!.controls[key];
  }

  protected submit(): void {
    const form = this.form();
    if (!form) return;
    this.submitted.set(true);
    form.markAllAsTouched();
    if (form.invalid) {
      const count = Object.values(form.controls).filter((c) => c.invalid).length;
      // Same text twice in a row is not re-announced: clear first, then set on the next tick.
      this.statusMessage.set('');
      queueMicrotask(() =>
        this.statusMessage.set(
          count === 1 ? 'Revisa el campo marcado.' : `Revisa los ${count} campos marcados.`,
        ),
      );
      this.focusFirstInvalid(form);
      return;
    }
    this.session.markStep1Completed();
    void this.router.navigate(['plans'], { relativeTo: this.route });
  }

  private focusFirstInvalid(form: Step1Group): void {
    for (const section of this.sections()) {
      for (const { field } of section.fields) {
        if (form.controls[field.key].invalid) {
          this.host.nativeElement.querySelector<HTMLElement>(`#${fieldInputId(field.key)}`)?.focus();
          return;
        }
      }
    }
  }
}
<section class="step1 py-4">
  <div class="row justify-content-center">
    <div class="col-12 col-lg-8">
  <app-stepper [steps]="steps" [current]="1" />

  <div class="step1__card">
    <header class="step1__header reveal" style="--reveal-index: 0">
      <h1 class="step1__heading" tabindex="-1">Cuéntanos de ti y de tu vehículo</h1>
      <p class="step1__subtitle">Te toma menos de 2 minutos.</p>
    </header>

    @if (loading()) {
      <div class="step1__skeleton" aria-busy="true">
        <span class="visually-hidden">Cargando formulario…</span>
        @for (n of [1, 2, 3, 4, 5, 6]; track n) {
          <div class="step1__skeleton-field" aria-hidden="true">
            <span class="step1__skeleton-label"></span>
            <span class="step1__skeleton-control"></span>
          </div>
        }
      </div>
    } @else if (failed()) {
      <div class="step1__error" role="alert">
        <p class="step1__error-title">
          <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
            <circle cx="12" cy="12" r="10" fill="none" stroke="currentColor" stroke-width="2" />
            <path d="M12 7v6M12 16.5v.5" stroke="currentColor" stroke-width="2" stroke-linecap="round" />
          </svg>
          No pudimos cargar el formulario.
        </p>
        <p class="step1__error-hint">Revisa tu conexión e inténtalo de nuevo.</p>
        <button type="button" class="button button--secondary" (click)="load()">Reintentar</button>
      </div>
    } @else if (isEmpty()) {
      <div class="step1__empty-state">
        <p class="step1__empty">Por ahora no hay datos que pedir para este país.</p>
        <button type="button" class="button button--secondary" (click)="load()">Reintentar</button>
      </div>
    } @else if (form(); as formGroup) {
      <form [formGroup]="formGroup" (ngSubmit)="submit()" novalidate>
        <p class="visually-hidden" aria-live="polite" data-testid="submit-status">{{ statusMessage() }}</p>
        @for (section of sections(); track section.id) {
          <h2 class="step1__section reveal" [style.--reveal-index]="section.titleDelay">
            @if (section.id === 'policyholder') {
              <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
                <circle cx="12" cy="8" r="4" fill="none" stroke="currentColor" stroke-width="2" />
                <path d="M4 21c0-4.4 3.6-7 8-7s8 2.6 8 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" />
              </svg>
            } @else {
              <svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true" focusable="false">
                <path d="M4 16v-4l2-5h12l2 5v4M4 16h16M4 16v2h3v-2M17 16v2h3v-2" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
                <circle cx="8" cy="13" r="1" fill="currentColor" />
                <circle cx="16" cy="13" r="1" fill="currentColor" />
              </svg>
            }
            {{ section.title }}
          </h2>
          <div class="row g-3">
            @for (item of section.fields; track item.field.key) {
              <div
                class="reveal"
                [class.col-12]="item.field.type === 'checkbox'"
                [class.col-md-6]="item.field.type !== 'checkbox'"
                [style.--reveal-index]="item.delay"
              >
                <app-form-field
                  [field]="item.field"
                  [control]="control(item.field.key)"
                  [submitted]="submitted()"
                />
              </div>
            }
          </div>
        }
        <div class="step1__actions d-flex justify-content-end reveal" [style.--reveal-index]="buttonDelay()">
          <button type="submit" class="button button--cta">
            Continuar
            <svg viewBox="0 0 16 16" width="16" height="16" aria-hidden="true" focusable="false">
              <path d="M3 8h10M9 4l4 4-4 4" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" />
            </svg>
          </button>
        </div>
      </form>
    }
  </div>
  </div>
    </div>
</section>
.step1 {
  &__card {
    margin-top: var(--space-4);
    padding: var(--space-6);
    border-radius: var(--radius-md);
    background: var(--color-surface);
    box-shadow: var(--shadow-card);
  }

  &__heading {
    margin: 0 0 var(--space-1);
    color: var(--color-brand);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }

    @media (min-width: 768px) {
      font-size: 32px;
    }
  }

  &__subtitle {
    margin: 0 0 var(--space-6);
    color: var(--color-text-muted);
  }

  &__section {
    display: flex;
    align-items: center;
    gap: var(--space-2);
    margin: var(--space-6) 0 var(--space-3);
    color: var(--color-action);
    font-size: 20px;
    font-weight: 700;
  }

  &__actions {
    margin-top: var(--space-8);

    .button--cta {
      width: 100%;

      @media (min-width: 576px) {
        width: auto;
      }
    }
  }

  &__empty-state {
    padding: var(--space-8) var(--space-4);
    text-align: center;

    p {
      margin: 0 0 var(--space-3);
      color: var(--color-text-muted);
    }
  }

  &__error {
    display: flex;
    flex-direction: column;
    gap: var(--space-3);
    align-items: flex-start;
    padding: var(--space-4);
    border: 1px solid var(--color-error);
    border-radius: var(--radius-sm);
    background: var(--color-error-bg);
    color: var(--color-error);
    font-weight: 500;

    p {
      margin: 0;
    }
  }

  &__error-title {
    display: flex;
    align-items: center;
    gap: var(--space-2);
  }

  &__error-hint {
    color: var(--color-text-muted);
    font-weight: 400;
  }

  &__skeleton {
    display: grid;
    grid-template-columns: 1fr;
    gap: var(--space-4);

    @media (min-width: 768px) {
      grid-template-columns: 1fr 1fr;
    }
  }

  &__skeleton-field {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
  }

  &__skeleton-label,
  &__skeleton-control {
    display: block;
    border-radius: 12px 12px 0 0;
    background: var(--color-surface-field-focus);
    animation: step1-pulse 1.4s ease-in-out infinite;
  }

  &__skeleton-label {
    width: 40%;
    height: 14px;
  }

  &__skeleton-control {
    height: 52px;
  }
}
/* First render after load only: items fade up one by one.
   `backwards` (not `both`): once finished, the animation no longer applies, so
   items leave no stacking context and an open select list stays on top. */
.reveal {
  animation: step1-reveal 600ms cubic-bezier(0.2, 0.7, 0.2, 1) backwards;
  animation-delay: calc(var(--reveal-index, 0) * 110ms);
}

@keyframes step1-reveal {
  from {
    opacity: 0;
    transform: translateY(14px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

@keyframes step1-pulse {
  50% {
    opacity: 0.5;
  }
}

@media (prefers-reduced-motion: reduce) {
  .reveal,
  .step1__skeleton-label,
  .step1__skeleton-control {
    animation: none;
  }
}

import { inject } from '@angular/core';
import { ActivatedRouteSnapshot, CanActivateFn, Router, UrlTree } from '@angular/router';
import { QuoteSessionStore } from '../../core/session/quote-session.store';

/** SC-002: step 2 opens only after step 1 was completed; otherwise back to step 1. */
export const step1CompleteGuard: CanActivateFn = (
  route: ActivatedRouteSnapshot,
): boolean | UrlTree => {
  if (inject(QuoteSessionStore).isStep1Completed()) return true;
  const country = route.parent?.paramMap.get('country') ?? route.paramMap.get('country') ?? '';
  return inject(Router).createUrlTree(['/', country, 'quote']);
};
import { EnvironmentInjector, runInInjectionContext } from '@angular/core';
import { TestBed } from '@angular/core/testing';
import { ActivatedRouteSnapshot, Router, RouterStateSnapshot, UrlTree, provideRouter } from '@angular/router';
import { beforeEach, describe, expect, it } from 'vitest';
import { QuoteSessionStore } from '../../core/session/quote-session.store';
import { step1CompleteGuard } from './step1-complete.guard';

describe('US-01 · SC-002 step 2 guard', () => {
  let session: QuoteSessionStore;

  const run = () =>
    runInInjectionContext(TestBed.inject(EnvironmentInjector), () =>
      step1CompleteGuard(
        { parent: { paramMap: { get: () => 'co' } } } as unknown as ActivatedRouteSnapshot,
        {} as RouterStateSnapshot,
      ),
    );

  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({ providers: [provideRouter([])] });
    session = TestBed.inject(QuoteSessionStore);
    session.start('co');
  });

  it('lets a completed step 1 through', () => {
    session.markStep1Completed();
    expect(run()).toBe(true);
  });

  it('redirects to step 1 of the same country when not completed', () => {
    const result = run() as UrlTree;
    expect(TestBed.inject(Router).serializeUrl(result)).toBe('/co/quote');
  });

  it('redirects again after step 1 is edited', () => {
    session.markStep1Completed();
    session.saveStep1({ fullName: 'Ana' });
    expect(run()).not.toBe(true);
  });
});
import {
  ChangeDetectionStrategy,
