:host {
  /* The card itself is the grid / slide item. */
  display: contents;
}

.plan-card {
  --plan-ring: var(--color-border);
  position: relative;
  display: grid;
  grid-template-rows: auto auto auto 1fr;
  flex: 1 1 auto;
  width: 100%;
  min-width: 0;
  padding: var(--space-6) var(--space-4);
  border: 1px solid var(--plan-ring);
  border-radius: 14px;
  background: var(--color-surface);
  cursor: pointer;

  /* From 992px the cards share the page grid, so the rows align across cards. */
  @media (min-width: 992px) {
    grid-row: span 4;
    grid-template-rows: subgrid;
    padding: var(--space-6);
  }

  &:hover {
    --plan-ring: var(--color-action);
  }

  &--recommended {
    --plan-ring: var(--color-brand);
    /* 5px top border instead of 1px: 4px less padding keeps the rows aligned. */
    padding-top: calc(var(--space-6) - 4px);
    border-top: 5px solid var(--color-brand);
    box-shadow: inset 0 0 0 1px var(--color-brand);

    &:hover {
      --plan-ring: var(--color-brand);
    }
  }

  &--selected,
  &--selected:hover {
    --plan-ring: var(--color-action);
    box-shadow: inset 0 0 0 1px var(--color-action);
  }

  &:has(.plan-card__input:focus-visible) {
    box-shadow:
      inset 0 0 0 1px var(--plan-ring),
      var(--focus-ring);
  }

  &__input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: 0;
    opacity: 0;
  }

  &__badge {
    position: absolute;
    top: -2.5px;
    left: 50%;
    z-index: 1;
    display: inline-flex;
    align-items: center;
    gap: var(--space-1);
    padding: 6px 18px;
    border-radius: var(--radius-pill);
    background: var(--color-cta);
    color: var(--color-on-cta);
    font-size: 16px;
    font-weight: 700;
    line-height: 1.2;
    white-space: nowrap;
    transform: translate(-50%, -50%);
  }

  &__head {
    display: flex;
    align-items: flex-start;
    gap: var(--space-3);
    padding-bottom: var(--space-4);
  }

  &__radio {
    flex: none;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 24px;
    height: 24px;
    margin-top: 2px;
    border: 2px solid var(--color-text-muted);
    border-radius: 50%;
    background: var(--color-surface);
    color: var(--color-surface);

    svg {
      opacity: 0;
    }
  }

  &--selected &__radio {
    border-color: var(--color-action);
    background: var(--color-action);

    svg {
      opacity: 1;
    }
  }

  &__title {
    display: flex;
    flex-direction: column;
    gap: var(--space-1);
    min-width: 0;
  }

  &__name {
    color: var(--color-action);
    font-size: 20px;
    font-weight: 700;
    line-height: 1.25;
  }

  &__description {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__price-row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-2);
    padding: var(--space-4) 0;
    border-top: 1px solid var(--color-border);
  }

  &__price {
    color: var(--color-brand);
    font-size: 32px;
    font-weight: 700;
    line-height: 1.1;
  }

  &__period {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__section {
    display: block;
    min-width: 0;

    &:not(:empty) {
      padding-bottom: var(--space-4);
    }
  }

  &__section-title {
    display: block;
    margin-bottom: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    font-weight: 700;
  }

  &__list {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  &__item {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    line-height: 1.4;

    svg {
      flex: none;
      margin-top: 2px;
      color: var(--color-brand);
    }
  }
}

