  }

  &__price-row {
    display: flex;
    flex-wrap: wrap;
    align-items: baseline;
    gap: var(--space-2);
    padding: var(--space-4) 0;
    border-top: 1px solid var(--color-border);
  }

  &__price {
    color: var(--color-brand);
    font-size: 32px;
    font-weight: 700;
    line-height: 1.1;
  }

  &__period {
    color: var(--color-text-muted);
    font-size: 14px;
    font-weight: 500;
  }

  &__section {
    display: block;
    min-width: 0;

    &:not(:empty) {
      padding-bottom: var(--space-4);
    }
  }

  &__section-title {
    display: block;
    margin-bottom: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    font-weight: 700;
  }

  &__list {
    display: flex;
    flex-direction: column;
    gap: var(--space-2);
    margin: 0;
    padding: 0;
    list-style: none;
  }

  &__item {
    display: flex;
    align-items: flex-start;
    gap: var(--space-2);
    color: var(--color-text);
    font-size: 14px;
    line-height: 1.4;

    svg {
      flex: none;
      margin-top: 2px;
      color: var(--color-brand);
    }
  }
}

