@use 'swiper/swiper.css';

.plan-list {
  /* Swiper theme */
  --swiper-theme-color: var(--color-action);

  &__header {
    margin: var(--space-6) 0 var(--space-4);
  }

  &__heading {
    margin: 0;
    color: var(--color-brand);
    font-size: 24px;
    font-weight: 700;

    &:focus {
      outline: none;
    }

    @media (min-width: 768px) {
      font-size: 32px;
    }
  }

  &__group {
    min-width: 0;
    margin: 0;
    padding: 0;
    border: 0;
  }

  /* Room above for the "Recomendado" pill that sits on the top border, and for the focus ring. */
  &__viewport {
    padding: var(--space-6) var(--space-1) var(--space-1);
  }

  /* Below 992px: the Swiper slider (classes toggled by the page). */
  &__item.swiper-slide {
    display: flex;
    height: auto;
  }

  /* From 992px: three columns; each item spans 4 rows that the cards share (subgrid). */
  @media (min-width: 992px) {
    &__track {
      display: grid;
      grid-template-columns: repeat(3, minmax(0, 1fr));
      column-gap: var(--space-6);
      row-gap: 0;
    }

    &__item {
      display: grid;
      grid-row: span 4;
      grid-template-rows: subgrid;
    }
  }

  &__controls {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-4);
    margin-top: var(--space-4);
  }

  &__nav {
    display: inline-flex;
    flex: none;
    align-items: center;
    justify-content: center;
    width: 48px;
    height: 48px;
    padding: 0;
    border: 1px solid var(--color-brand);
    border-radius: 50%;
    background: var(--color-surface);
    color: var(--color-brand);
    cursor: pointer;

    &:hover:not(:disabled) {
      background: var(--color-surface-alt);
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--focus-ring);
    }

    &:disabled,
    &.swiper-button-disabled {
      border-color: transparent;
      background: var(--color-disabled-bg);
      color: var(--color-disabled-text);
      cursor: not-allowed;
    }
  }

  &__dots {
    display: flex;
    align-items: center;
    gap: var(--space-3);
  }

  &__dots .swiper-pagination-bullet {
    position: relative;
    width: 12px;
    height: 12px;
    border-radius: 50%;
    background: var(--color-border);
    cursor: pointer;

    /* Bigger touch target around the small dot. */
    &::after {
      content: '';
      position: absolute;
      inset: -18px -6px;
    }

    &:focus-visible {
      outline: none;
      box-shadow: var(--focus-ring);
    }
  }

  &__dots .swiper-pagination-bullet-active {
    background: var(--color-action);
  }

  &__actions {
